import { useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';

import {
  useBffData,
  useMediaQuery,
  usePageFilterApplied,
  useSubFilters,
} from 'hooks';
import { BigNumberSparkLineCardData } from 'pages/components';

import {
  CONNECTIONS_CREATIVITY_HOME_PAGE_NAME,
  RESOURCE_ALLOCATION_ROUTE,
  type ResourceAllocationCardKey,
} from '../constants';
import type {
  ConnectionsCreativityHomePageDataState,
  ConnectionsCreativityMainCardsData,
  ResourceAllocationCardsData,
} from '../types';

export const useConnectionsCreativityHomePageData = () => {
  const isDesktopLarge = useMediaQuery('(min-width: 1440px)');
  const navigate = useNavigate();
  const { setSubFilterValue } = useSubFilters();
  const { applied } = usePageFilterApplied(
    CONNECTIONS_CREATIVITY_HOME_PAGE_NAME,
  );

  const pageData = useBffData({
    id: 'connections-and-creativity_home_home',
    kpiGroup: 'media',
    subFilters: {
      zone: applied.zone,
      country: applied.country,
    },
  });

  const mainCardsData = useMemo((): ConnectionsCreativityMainCardsData => {
    const data = (pageData?.data?.[
      'connections-and-creativity-home-big-numbers-trend'
    ] || []) as unknown as BigNumberSparkLineCardData[];

    return {
      mediaEffectiveness:
        data.find((item) => item.chartTitle === 'Media Spend') || null,
      businessEfficiency:
        data.find((item) => item.chartTitle === 'Non-Working Money') || null,
    };
  }, [pageData]);

  const resourceAllocationCardsData = useMemo(
    (): ResourceAllocationCardsData | undefined =>
      pageData?.data?.[
        'connections-and-creativity-home-resource-allocation'
      ] as ResourceAllocationCardsData | undefined,
    [pageData],
  );

  const onSparklineCardClick = useCallback(() => {
    navigate(RESOURCE_ALLOCATION_ROUTE);
  }, [navigate]);

  const onResourceAllocationCardClick = useCallback(
    (key: ResourceAllocationCardKey) => {
      if (key === 'megabrandsQwoaBigNumber') {
        setSubFilterValue('kpis', 'media_qwoa');
        navigate(
          `/connections-creativity/resource-allocation-media/media-drilldown`,
        );
        return;
      }

      if (key === 'campaignsQwoaBigNumber') {
        setSubFilterValue('kpis', 'campaign_qwoa');
        navigate(
          `/connections-creativity/resource-allocation-media/media-drilldown`,
        );
      }
    },
    [navigate, setSubFilterValue],
  );

  const pageDataState = useMemo(
    (): ConnectionsCreativityHomePageDataState => ({
      data: pageData?.data,
      loading: pageData?.loading,
      error: pageData?.error,
    }),
    [pageData?.data, pageData?.error, pageData?.loading],
  );

  return {
    isDesktopLarge,
    pageData: pageDataState,
    mainCardsData,
    resourceAllocationCardsData,
    onSparklineCardClick,
    onResourceAllocationCardClick,
  };
};

export type ConnectionsCreativityHomePageDataBundle = ReturnType<
  typeof useConnectionsCreativityHomePageData
>;
